using System;
using System.Collections;
using System.Linq;
using System.Reflection;
using NUnit.Framework;
using SDGAdventure.SharedPlayer;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
namespace M7SharedPlayerTests {
 public sealed class Level04WorldPickupTests {
  const string Scene="Assets/_Modules_/02_Levels/Level04/Imported/Scenes/SampleScene.unity",Id="level04_plasma_gun";
  [UnityTest] public IEnumerator ActualScenePickupRequiresActionAndRespectsWallsAndUi(){
   var oldBg=InputSystem.settings.backgroundBehavior;var oldEditor=InputSystem.settings.editorInputBehaviorInPlayMode;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;var keyboard=InputSystem.AddDevice<Keyboard>();PlayerCursor.BeginSimulation(CursorLockMode.Locked);var input=PlayerInputService.Instance;var action=input.Actions.FindAction("Gameplay/Interact");var dropAction=input.Actions.FindAction("Gameplay/Drop");string old=action.bindings[0].overridePath,oldDrop=dropAction.bindings[0].overridePath;object bag=null;Type bt=Type.GetType("EcoAdventureRuntime, Assembly-CSharp",true);GameObject blocker=null;
   try{action.ApplyBindingOverride(0,"<Keyboard>/n");dropAction.ApplyBindingOverride(0,"<Keyboard>/m");SceneManager.LoadScene(Scene);yield return null;yield return null;bag=bt.GetProperty("Instance").GetValue(null);var has=bt.GetMethod("Has");Assert.IsFalse((bool)has.Invoke(bag,new object[]{Id,1}));var pickup=(Component)UnityEngine.Object.FindFirstObjectByType(Type.GetType("SDGAdventure.Level04.Level04PlasmaPickup, Assembly-CSharp",true));var legacy=pickup.GetComponent(Type.GetType("WeaponPickup, Assembly-CSharp",true)) as Behaviour;Assert.IsFalse(legacy.enabled);var box=pickup.GetComponent<BoxCollider>();Assert.IsFalse(box.isTrigger);Assert.Less(Vector3.Distance(box.bounds.center,pickup.GetComponentsInChildren<Renderer>().First(r=>!r.name.StartsWith("V11_HintOverlay_")).bounds.center),1.8f);
    var player=UnityEngine.Object.FindFirstObjectByType<SharedFirstPersonController>();var controller=player.GetComponent<CharacterController>();var rig=player.GetComponent<PlayerPerspectiveRig>();var camera=Camera.main;var interactor=player.GetComponent<PlayerInteractor>();var hud=player.GetComponent<PlayerHudCanvas>();player.enabled=false;rig.enabled=false;controller.enabled=false;player.transform.position=new Vector3(box.bounds.center.x,.55f,box.bounds.center.z-2.2f);controller.enabled=true;camera.transform.LookAt(box.bounds.center);Physics.SyncTransforms();yield return null;yield return null;
    Assert.IsTrue(pickup.gameObject.activeInHierarchy);Assert.IsFalse((bool)has.Invoke(bag,new object[]{Id,1}),"Approach must not pick up");Assert.AreSame(pickup,interactor.FindTarget(),"Actual scene gun collider must be the aimed target");Assert.That(hud.PromptText,Does.Contain("拾取電漿槍"));Assert.That(hud.PromptText.ToUpperInvariant(),Does.Contain("N"));Assert.IsTrue(pickup.GetComponentsInChildren<Renderer>().Any(r=>r.name.StartsWith("V11_HintOverlay_")&&r.enabled),"Nearby visible gun should be highlighted");
    blocker=GameObject.CreatePrimitive(PrimitiveType.Cube);blocker.transform.position=Vector3.Lerp(camera.transform.position,box.bounds.center,.5f);blocker.transform.localScale=Vector3.one*.65f;Physics.SyncTransforms();yield return null;Assert.IsNull(interactor.FindTarget(),"Wall blocks pickup");InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.N));InputSystem.Update();yield return null;Assert.IsFalse((bool)has.Invoke(bag,new object[]{Id,1}));InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.Update();UnityEngine.Object.DestroyImmediate(blocker);blocker=null;Physics.SyncTransforms();yield return null;
    input.SetContext(PlayerInputContext.UI);InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.N));InputSystem.Update();yield return null;Assert.IsFalse((bool)has.Invoke(bag,new object[]{Id,1}),"UI blocks pickup");InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.Update();input.SetContext(PlayerInputContext.Gameplay);yield return null;
    InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.N));InputSystem.Update();yield return null;InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.Update();yield return null;Assert.IsTrue((bool)has.Invoke(bag,new object[]{Id,1}));Assert.IsFalse((bool)has.Invoke(bag,new object[]{Id,2}));Assert.IsFalse(pickup.gameObject.activeSelf);var slots=(string[])bt.GetField("quickSlots").GetValue(bag);Assert.AreEqual(Array.IndexOf(slots,Id),bt.GetField("selectedSlot").GetValue(bag));Assert.GreaterOrEqual(Array.IndexOf(slots,Id),0); InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.M));yield return null;InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.Update();yield return null;Assert.IsFalse((bool)has.Invoke(bag,new object[]{Id,1}),"Drop action removes the equipped gun");var dropped=GameObject.Find("DroppedLevel04Plasma");Assert.NotNull(dropped);camera.transform.LookAt(dropped.GetComponent<Collider>().bounds.center);Physics.SyncTransforms();yield return null;Assert.AreSame(dropped.GetComponent(Type.GetType("SDGAdventure.Level04.Level04PlasmaPickup, Assembly-CSharp",true)),interactor.FindTarget());InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.N));InputSystem.Update();yield return null;InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.Update();yield return null;Assert.IsTrue((bool)has.Invoke(bag,new object[]{Id,1}));Assert.IsFalse((bool)has.Invoke(bag,new object[]{Id,2}));SceneManager.LoadScene(Scene);yield return null;yield return null;var source=(Component)UnityEngine.Object.FindFirstObjectByType(Type.GetType("SDGAdventure.Level04.Level04PlasmaPickup, Assembly-CSharp",true),FindObjectsInactive.Include);Assert.NotNull(source);Assert.IsFalse(source.gameObject.activeSelf,"Previously collected scene gun must not duplicate after reload");Assert.IsTrue((bool)has.Invoke(bag,new object[]{Id,1}));
   }finally{if(blocker)UnityEngine.Object.DestroyImmediate(blocker);if(bag!=null&&(bool)bt.GetMethod("Has").Invoke(bag,new object[]{Id,1}))bt.GetMethod("Consume").Invoke(bag,new object[]{Id,1});if(old==null)action.RemoveBindingOverride(0);else action.ApplyBindingOverride(0,old);if(oldDrop==null)dropAction.RemoveBindingOverride(0);else dropAction.ApplyBindingOverride(0,oldDrop);input.SetContext(PlayerInputContext.Gameplay);PlayerCursor.EndSimulation();InputSystem.RemoveDevice(keyboard);InputSystem.settings.backgroundBehavior=oldBg;InputSystem.settings.editorInputBehaviorInPlayMode=oldEditor;}
  }
 }
}
